/// the envelope major version differs (VERSION_MISMATCH)
pub const STATUS_FLAGS_VERSION_MISMATCH: u32 = 0x1;
/// no slab of the class and the arena cannot grow
pub const STATUS_FLAGS_ARENA_FULL: u32 = 0x2;
/// the inbox could not take a message
pub const STATUS_FLAGS_INBOX_OVERFLOW: u32 = 0x4;
/// the adaptive voice cap is limiting voices
pub const STATUS_FLAGS_ADAPTIVE_CAP_ACTIVE: u32 = 0x8;
/// the core is initialised and rendering
pub const STATUS_FLAGS_READY: u32 = 0x10;
/// a trap was caught in the render path
pub const STATUS_FLAGS_TRAP_CAUGHT: u32 = 0x20;
