/// A whole STATUS message (kind 9), envelope included.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct StatusBlock {
    pub current_frame: f64,
    pub date_ms: f64,
    pub ping_seq: u32,
    pub ping_frame_lo: u32,
    pub underruns: u32,
    pub late_commands: u32,
    pub work_units: u32,
    pub work_units_max: u32,
    pub mixed_voices: u16,
    pub live_voices: u16,
    pub flags: u32,
    pub mixed_cap: u16,
    pub load_permille: u16,
    pub traps: u16,
    pub min_slack_frames: i32,
    pub underrun_frames: u32,
    pub arena_used_kb: u32,
    pub arena_largest_free_kb: u32,
    pub abi_version: u32,
    pub max_lateness_frames: u32,
    pub hrtf_voices: u16,
    pub hrtf_load_failure: u16,
    /// voices that ended in this block
    /// At most 1024 per block.
    pub ended: Vec<u32>,
    /// voices virtualised by the adaptive cap
    /// At most 1024 per block.
    pub demoted: Vec<u32>,
    /// voices that starved this block; the rest carry over
    /// At most 1024 per block.
    pub starved: Vec<u32>,
    /// playheads of looping, streamed and long clips, round-robin
    /// At most 256 per block.
    pub playheads: Vec<StatusPlayheadsItem>,
    /// ClipEvent codes: 1 resident, 2 refusedCeiling, 3 refusedGrow, 4 hrtfReady
    /// At most 64 per block.
    pub clip_events: Vec<StatusClipEventsItem>,
    /// StreamEvent codes: 1 starved, 2 eos, 3 error
    /// At most 64 per block.
    pub stream_events: Vec<StatusStreamEventsItem>,
    /// peak level per bus, left and right
    /// At most 32 per block.
    pub peaks: Vec<StatusPeaksItem>,
}

impl StatusBlock {
    /// Write the whole message at `base` (envelope first); returns the bytes written.
    pub fn write(&self, out: &mut [u8], base: usize, seq: u32) -> Result<usize, i32> {
        if base + 112 > out.len() {
            return Err(ERR_OVERSIZE);
        }
        put_f64(out, base + 16, self.current_frame);
        put_f64(out, base + 24, self.date_ms);
        put_u32(out, base + 32, self.ping_seq);
        put_u32(out, base + 36, self.ping_frame_lo);
        put_u32(out, base + 40, self.underruns);
        put_u32(out, base + 44, self.late_commands);
        put_u32(out, base + 48, self.work_units);
        put_u32(out, base + 52, self.work_units_max);
        put_u16(out, base + 56, self.mixed_voices);
        put_u16(out, base + 58, self.live_voices);
        put_u32(out, base + 60, self.flags);
        if self.ended.len() > 1024 {
            return Err(ERR_OVERSIZE);
        }
        put_u16(out, base + 64, self.ended.len() as u16);
        if self.demoted.len() > 1024 {
            return Err(ERR_OVERSIZE);
        }
        put_u16(out, base + 66, self.demoted.len() as u16);
        if self.starved.len() > 1024 {
            return Err(ERR_OVERSIZE);
        }
        put_u16(out, base + 68, self.starved.len() as u16);
        if self.playheads.len() > 256 {
            return Err(ERR_OVERSIZE);
        }
        put_u16(out, base + 70, self.playheads.len() as u16);
        if self.peaks.len() > 32 {
            return Err(ERR_OVERSIZE);
        }
        put_u16(out, base + 72, self.peaks.len() as u16);
        if self.clip_events.len() > 64 {
            return Err(ERR_OVERSIZE);
        }
        put_u16(out, base + 74, self.clip_events.len() as u16);
        if self.stream_events.len() > 64 {
            return Err(ERR_OVERSIZE);
        }
        put_u16(out, base + 76, self.stream_events.len() as u16);
        put_u16(out, base + 78, self.mixed_cap);
        put_u16(out, base + 80, self.load_permille);
        put_u16(out, base + 82, self.traps);
        put_i32(out, base + 84, self.min_slack_frames);
        put_u32(out, base + 88, self.underrun_frames);
        put_u32(out, base + 92, self.arena_used_kb);
        put_u32(out, base + 96, self.arena_largest_free_kb);
        put_u32(out, base + 100, self.abi_version);
        put_u32(out, base + 104, self.max_lateness_frames);
        put_u16(out, base + 108, self.hrtf_voices);
        put_u16(out, base + 110, self.hrtf_load_failure);
        let mut cur = base + 112;
        if cur + self.ended.len() * 4 > out.len() {
            return Err(ERR_OVERSIZE);
        }
        for v in &self.ended {
            put_u32(out, cur, *v);
            cur += 4;
        }
        if cur + self.demoted.len() * 4 > out.len() {
            return Err(ERR_OVERSIZE);
        }
        for v in &self.demoted {
            put_u32(out, cur, *v);
            cur += 4;
        }
        if cur + self.starved.len() * 4 > out.len() {
            return Err(ERR_OVERSIZE);
        }
        for v in &self.starved {
            put_u32(out, cur, *v);
            cur += 4;
        }
        if cur + self.playheads.len() * 8 > out.len() {
            return Err(ERR_OVERSIZE);
        }
        for v in &self.playheads {
            v.write(out, cur)?;
            cur += 8;
        }
        if cur + self.clip_events.len() * 8 > out.len() {
            return Err(ERR_OVERSIZE);
        }
        for v in &self.clip_events {
            v.write(out, cur)?;
            cur += 8;
        }
        if cur + self.stream_events.len() * 8 > out.len() {
            return Err(ERR_OVERSIZE);
        }
        for v in &self.stream_events {
            v.write(out, cur)?;
            cur += 8;
        }
        if cur + self.peaks.len() * 8 > out.len() {
            return Err(ERR_OVERSIZE);
        }
        for v in &self.peaks {
            v.write(out, cur)?;
            cur += 8;
        }
        Envelope::new(kind::STATUS, seq, (cur - base - 16) as u32).write(out, base)?;
        Ok(cur - base)
    }
    /// Read a whole STATUS message at `base`; the envelope is checked for magic, major and kind.
    pub fn read(buf: &[u8], base: usize) -> Result<(Self, usize), i32> {
        if base.checked_add(112).map_or(true, |e| e > buf.len()) {
            return Err(ERR_TRUNCATED);
        }
        let (env, _) = Envelope::read(buf, base)?;
        if env.magic != MAGIC {
            return Err(ERR_BAD_MAGIC);
        }
        if (env.version >> 8) as u32 != VERSION_MAJOR {
            return Err(ERR_VERSION_MISMATCH);
        }
        if env.kind != kind::STATUS {
            return Err(ERR_MALFORMED);
        }
        let limit = base.checked_add(16 + env.body_bytes as usize).filter(|l| *l <= buf.len()).ok_or(ERR_TRUNCATED)?;
        let current_frame = get_f64(buf, base + 16);
        let date_ms = get_f64(buf, base + 24);
        let ping_seq = get_u32(buf, base + 32);
        let ping_frame_lo = get_u32(buf, base + 36);
        let underruns = get_u32(buf, base + 40);
        let late_commands = get_u32(buf, base + 44);
        let work_units = get_u32(buf, base + 48);
        let work_units_max = get_u32(buf, base + 52);
        let mixed_voices = get_u16(buf, base + 56);
        let live_voices = get_u16(buf, base + 58);
        let flags = get_u32(buf, base + 60);
        let ended_count = get_u16(buf, base + 64);
        let demoted_count = get_u16(buf, base + 66);
        let starved_count = get_u16(buf, base + 68);
        let playhead_count = get_u16(buf, base + 70);
        let bus_count = get_u16(buf, base + 72);
        let clip_event_count = get_u16(buf, base + 74);
        let stream_event_count = get_u16(buf, base + 76);
        let mixed_cap = get_u16(buf, base + 78);
        let load_permille = get_u16(buf, base + 80);
        let traps = get_u16(buf, base + 82);
        let min_slack_frames = get_i32(buf, base + 84);
        let underrun_frames = get_u32(buf, base + 88);
        let arena_used_kb = get_u32(buf, base + 92);
        let arena_largest_free_kb = get_u32(buf, base + 96);
        let abi_version = get_u32(buf, base + 100);
        let max_lateness_frames = get_u32(buf, base + 104);
        let hrtf_voices = get_u16(buf, base + 108);
        let hrtf_load_failure = get_u16(buf, base + 110);
        let mut cur = base + 112;
        if ended_count as usize > 1024 || (ended_count as usize) * 4 > limit - cur {
            return Err(ERR_OVERSIZE);
        }
        let mut ended = Vec::with_capacity(ended_count as usize);
        for _ in 0..ended_count {
            ended.push(get_u32(buf, cur));
            cur += 4;
        }
        if demoted_count as usize > 1024 || (demoted_count as usize) * 4 > limit - cur {
            return Err(ERR_OVERSIZE);
        }
        let mut demoted = Vec::with_capacity(demoted_count as usize);
        for _ in 0..demoted_count {
            demoted.push(get_u32(buf, cur));
            cur += 4;
        }
        if starved_count as usize > 1024 || (starved_count as usize) * 4 > limit - cur {
            return Err(ERR_OVERSIZE);
        }
        let mut starved = Vec::with_capacity(starved_count as usize);
        for _ in 0..starved_count {
            starved.push(get_u32(buf, cur));
            cur += 4;
        }
        if playhead_count as usize > 256 || (playhead_count as usize) * 8 > limit - cur {
            return Err(ERR_OVERSIZE);
        }
        let mut playheads = Vec::with_capacity(playhead_count as usize);
        for _ in 0..playhead_count {
            let (v, n) = StatusPlayheadsItem::read(buf, cur)?;
            playheads.push(v);
            cur += n;
        }
        if clip_event_count as usize > 64 || (clip_event_count as usize) * 8 > limit - cur {
            return Err(ERR_OVERSIZE);
        }
        let mut clip_events = Vec::with_capacity(clip_event_count as usize);
        for _ in 0..clip_event_count {
            let (v, n) = StatusClipEventsItem::read(buf, cur)?;
            clip_events.push(v);
            cur += n;
        }
        if stream_event_count as usize > 64 || (stream_event_count as usize) * 8 > limit - cur {
            return Err(ERR_OVERSIZE);
        }
        let mut stream_events = Vec::with_capacity(stream_event_count as usize);
        for _ in 0..stream_event_count {
            let (v, n) = StatusStreamEventsItem::read(buf, cur)?;
            stream_events.push(v);
            cur += n;
        }
        if bus_count as usize > 32 || (bus_count as usize) * 8 > limit - cur {
            return Err(ERR_OVERSIZE);
        }
        let mut peaks = Vec::with_capacity(bus_count as usize);
        for _ in 0..bus_count {
            let (v, n) = StatusPeaksItem::read(buf, cur)?;
            peaks.push(v);
            cur += n;
        }
        Ok((Self {
            current_frame,
            date_ms,
            ping_seq,
            ping_frame_lo,
            underruns,
            late_commands,
            work_units,
            work_units_max,
            mixed_voices,
            live_voices,
            flags,
            mixed_cap,
            load_permille,
            traps,
            min_slack_frames,
            underrun_frames,
            arena_used_kb,
            arena_largest_free_kb,
            abi_version,
            max_lateness_frames,
            hrtf_voices,
            hrtf_load_failure,
            ended,
            demoted,
            starved,
            playheads,
            clip_events,
            stream_events,
            peaks,
        }, limit - base))
    }
}
